import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    x = int(data[1])

    pos = x
    for i in range(n, 0, -1):
        if i % 2 == 1:
            if pos == 0:
                pos = 1
            elif pos == 1:
                pos = 0
        else:
            if pos == 1:
                pos = 2
            elif pos == 2:
                pos = 1

    print(pos)

if __name__ == "__main__":
    main()
